"""Write corpus/REVISION-2.md: every case changed or added by revision 2, with its logged rules and admission change.
Usage: rev2_summary.py <corpus_dir>"""
import collections, glob, json, os, sys

corpus = sys.argv[1]
cs = [json.load(open(p)) for p in sorted(glob.glob(os.path.join(corpus, 'cases', '*.json')))]
changed = [c for c in cs if c['revisions']]; added = [c for c in cs if c.get('added_in')]
rules = collections.Counter(r['rule'].split(':')[0] for c in cs for r in c['revisions'])
L = ['# Corpus revision 2 (contract `1.1-s1`, P1.29)', '',
     'Generated by `tools/rev2_summary.py`. Revision 1 is preserved unchanged in P1.28 (`~/cbm-work/p128-s1/corpus`). '
     'Every changed normative field is logged in its case\'s `revisions` list, and `validate_corpus.py revisions` proves that '
     'undoing those entries restores the revision-1 case exactly (apart from the contract string, the new `forwarding` fact, '
     'the log itself and an appended rationale).', '',
     f'**Totals.** {len(cs)} cases: {len(cs) - len(added)} from revision 1, of which {len(changed)} changed and '
     f'{len(cs) - len(added) - len(changed)} unchanged apart from the contract string and the `forwarding` fact; {len(added)} added.', '',
     '| Rule | Field changes |', '|---|---|']
L += [f'| {r} | {n} |' for r, n in sorted(rules.items())]
L += ['', '## Changed cases', '', '| Case | Role | Class | Rules | Admission (first change) | A1.3.4 |', '|---|---|---|---|---|---|']
for c in changed:
    rs = ', '.join(sorted({r['rule'].split(':')[0] for r in c['revisions']}))
    ad = next((f'{r["field"].split("/")[0]}: {r["from"]} → {r["to"]}' for r in c['revisions'] if r['field'].endswith('admission.decision')), 'unchanged')
    L.append(f'| `{c["case_id"]}` | {c["role"]} | {c["class"]} | {rs} | {ad} | {(c["historical"].get("a134_086bdec1") or {}).get("decision")} |')
L += ['', '## Added cases', '', '| Case | Rule | Evaluations | A1.3.4 (first evaluation) |', '|---|---|---|---|']
for c in added:
    evs = '; '.join(f'{e["name"]}: {e["expected"]["admission"]["decision"]}' for e in c['evaluations'])
    L.append(f'| `{c["case_id"]}` | {c["provenance"]["origin"].split("::")[1]} | {evs} | {(c["historical"].get("a134_086bdec1") or {}).get("decision")} |')
open(os.path.join(corpus, 'REVISION-2.md'), 'w').write('\n'.join(L) + '\n')
print(f'{len(changed)} changed, {len(added)} added')
